using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "DiscardWithActionAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/DiscardWithActionAction")]
public class DiscardWithActionAction : ChooseDiceAction
{
	[Header("Discard With Action Action")]
	[SerializeField]
	protected ListDiceInstanceEvent OnDiscardUsedDicesWithoutExhaust;

	[SerializeField]
	private bool enableFixedActionAmount;

	[SerializeField]
	[ShowIf("enableFixedActionAmount")]
	private int fixedActionAmount;

	[Header("Second Action")]
	[SerializeField]
	protected BattleAction battleAction;

	[SerializeField]
	protected OmenLogic targetToApplyActionLogic;

	[Header("Description")]
	[SerializeField]
	private bool dontAppendIfYouDoToDescription;

	public int FixedActionAmount => fixedActionAmount;

	public BattleAction BattleAction => battleAction;

	public bool DontAppendIfYouDoToDescription => dontAppendIfYouDoToDescription;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (playerHand)
		{
			return ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() > 1;
		}
		return ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() > 0;
	}

	public override void Cast(GameObject source)
	{
		if (diceList.Count == 0)
		{
			for (int i = 0; i < ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount(); i++)
			{
				diceList.Add(ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInstanceFromHand(i));
			}
		}
		CastAmount(diceList.Count, source);
	}

	public override void CastAmount(int amount, GameObject source)
	{
		OnDiscardUsedDicesWithoutExhaust.Raise(diceList);
		if (battleAction is RandomEnemyLightningAction)
		{
			(battleAction as RandomEnemyLightningAction).CastVariableAndTimesAmount(amount, fixedActionAmount, source);
		}
		else
		{
			int num = amount;
			if (enableFixedActionAmount)
			{
				num *= fixedActionAmount;
			}
			targetToApplyActionLogic.ActivateOmen(battleAction, num, null, source);
		}
		if (battleAction is PurifyAction || battleAction is RandomEnemyLightningAction)
		{
			CastWithPossibleRandomPurifyAsSecondAction();
		}
	}
}
